let chatId = null;

const runData = $json.execution?.data?.resultData?.runData || {};

try {
  chatId = runData['Extract Telegram Metadata']?.[0]?.data?.main?.[0]?.[0]?.json?.chatId;
} catch(e) {}

if (!chatId) {
  try {
    chatId = runData['Validate App Token1']?.[0]?.data?.main?.[0]?.[0]?.json?.chatId;
  } catch(e) {}
}

if (!chatId) {
  try {
    chatId = runData['Event Normalizer1']?.[0]?.data?.main?.[0]?.[0]?.json?.chatId;
  } catch(e) {}
}

if (!chatId) {
  chatId = '6319626617';
}

return {
  json: {
    chatId: chatId,
    errorMsg: $json.execution?.error?.message || $json.error?.message || 'Unknown error'
  }
};

const users = $input.all();
const webhookItem = $('Android SMS Webhook1').item.json;
const payload = webhookItem.body || {};
const headers = webhookItem.headers || {};
const token = headers['x-sms-api-key'] || payload.appToken;

const validUsers = users.filter(u => u.json && u.json.appToken && u.json.appToken != '');
const foundUser = validUsers.find(u => u.json.appToken === token);

if (foundUser && foundUser.json && foundUser.json.sheetId) {
  const messagesArray = Array.isArray(payload) ? payload : (Array.isArray(payload.messages) ? payload.messages : null);

  if (messagesArray && messagesArray.length > 0) {
    // 1. Process 1-Month Bulk SMS as Pretext Financial Dataset
    let totalSpent = 0;
    let totalIncome = 0;
    let maxExpense = 0;
    let maxVendor = 'Unknown';
    let minExpense = Infinity;
    let minVendor = 'Unknown';
    const categoryCounts = {};
    const categoryTotals = {};

    const transactions = [];

    for (const msgObj of messagesArray) {
      const amt = parseFloat(msgObj.amount) || 0;
      if (amt <= 0) continue; // Skip non-financial entries

      const rawType = (msgObj.type || '').toLowerCase();
      const isIncome = rawType === 'credit' || rawType === 'income';
      const type = isIncome ? 'Income' : 'Expense';

      const party = (msgObj.targetParty || msgObj.sender || msgObj.senderName || 'Unknown').trim();
      const desc = msgObj.description || msgObj.message || msgObj.sms_text || '';
      const medium = msgObj.medium || 'bank';
      const date = msgObj.extractedDate || (msgObj.datetime_readable ? msgObj.datetime_readable.split(' ')[0] : (msgObj.date || new Date().toISOString().split('T')[0]));

      // Intelligent financial categorization without questions
      let cat = 'Other Expense';
      const lower = `${party} ${desc}`.toLowerCase();
      if (/swiggy|zomato|zepto|blinkit|eat|food|cafe|restaurant|tea|chai|mcdonald|kfc|starbucks|domino|pizza|dine|biryani|bakery/i.test(lower)) {
        cat = 'Food & Groceries';
      } else if (/uber|ola|rapido|metro|irctc|railway|train|flight|bus|petrol|fuel|shell|hp|indianoil/i.test(lower)) {
        cat = 'Transport & Commute';
      } else if (/amazon|flipkart|myntra|meesho|zara|h&m|nykaa|ajio|croma|shopping|store|mart|supermarket/i.test(lower)) {
        cat = 'Shopping & Lifestyle';
      } else if (/electricity|water|gas|wifi|broadband|airtel|jio|vi|bill|recharge|dth|bescom|adani/i.test(lower)) {
        cat = 'Housing & Utilities';
      } else if (/netflix|spotify|prime|hotstar|pvr|inox|movie|entertainment|youtube/i.test(lower)) {
        cat = 'Entertainment & Leisure';
      } else if (/apollo|pharmeasy|1mg|cult|gym|hospital|clinic|pharmacy|med|fit/i.test(lower)) {
        cat = 'Health & Wellness';
      } else if (/emi|loan|credit card|card payment|bajaj finance/i.test(lower)) {
        cat = 'Debt & EMI';
      } else if (/salary|stipend|payroll|employer/i.test(lower)) {
        cat = 'Salary Income';
      } else if (isIncome) {
        cat = 'Other Income';
      }

      // Track Pretext Statistics
      if (isIncome) {
        totalIncome += amt;
      } else {
        totalSpent += amt;
        if (amt > maxExpense) {
          maxExpense = amt;
          maxVendor = party;
        }
        if (amt < minExpense) {
          minExpense = amt;
          minVendor = party;
        }
        categoryTotals[cat] = (categoryTotals[cat] || 0) + amt;
        categoryCounts[cat] = (categoryCounts[cat] || 0) + 1;
      }

      transactions.push({
        amount: amt,
        vendor: party,
        category: cat,
        type: type,
        medium: medium,
        description: desc,
        date: date
      });
    }

    if (minExpense === Infinity) minExpense = 0;

    const topCategories = Object.entries(categoryTotals)
      .sort((a, b) => b[1] - a[1])
      .map(([cat, total]) => ({
        category: cat,
        total: total,
        count: categoryCounts[cat] || 0
      }));

    return [{
      json: {
        isBulk: true,
        source: 'android_sms_bulk',
        sheetId: foundUser.json.sheetId,
        chatId: foundUser.json.chatId,
        directTransactions: transactions,
        analytics: {
          totalCount: transactions.length,
          totalSpent,
          totalIncome,
          maxExpense,
          maxVendor,
          minExpense,
          minVendor,
          topCategories
        }
      }
    }];
  } else {
    // Single realtime SMS
    return [{
      json: {
        sender: payload.sender || payload.senderName || 'Bank',
        message: payload.message || payload.sms_text || payload.text || '',
        isRegisteredUser: true,
        sheetId: foundUser.json.sheetId,
        chatId: foundUser.json.chatId,
        source: 'android_sms',
        isBulk: false
      }
    }];
  }
} else {
  throw new Error('Invalid appToken or user not found');
}

let text = '';
let chatId = $input.item.json.chatId || '';
let sheetId = $input.item.json.sheetId || '';
let source = $input.item.json.source || '';
let firstName = $input.item.json.firstName || 'User';
let isBulk = $input.item.json.isBulk || false;
let directTransactions = $input.item.json.directTransactions || null;
let analytics = $input.item.json.analytics || null;

if (source === 'android_sms_bulk') {
  text = 'Bulk 1-month SMS sync';
} else if (source === 'android_sms' || $input.item.json.message || $input.item.json.sms_text) {
  const msg = $input.item.json.message || $input.item.json.sms_text || '';
  const sender = $input.item.json.sender || $input.item.json.senderName || 'Bank';
  text = `SMS from ${sender}: ${msg}`;
  source = 'android_sms';
} else {
  text = $input.item.json.text;
  source = 'telegram';
}

return {
  json: {
    text,
    chatId,
    sheetId,
    source,
    firstName,
    sessionId: chatId,
    isBulk,
    directTransactions,
    analytics
  }
};

const chatRows = $input.all();
const norm = $('Event Normalizer').item.json;

const currentText = norm.text || '';
const chatId = norm.chatId || '';
const sheetId = norm.sheetId || '';
const firstName = norm.firstName || 'User';
const source = norm.source || 'unknown';
const sessionId = norm.sessionId || `${chatId}_${new Date().getTime()}`;
const today = new Date().toISOString().split('T')[0];

// Resilient extraction: accept content, text, agentResponse, message and resolve role
const sessionRows = chatRows
  .map(r => r.json)
  .filter(r => r && (r.content || r.text || r.agentResponse || r.message))
  .map(r => {
    let role = r.role || '';
    if (!role) {
      if (r.agentId === 'user' || r.text) role = 'user';
      else role = 'assistant';
    } else {
      role = String(role).toLowerCase();
    }
    const text = r.content || r.text || r.agentResponse || r.message || '';
    return {
      role: role === 'user' ? 'user' : 'assistant',
      content: String(text).trim()
    };
  })
  .filter(r => r.content.length > 0);

const recentRows = sessionRows.slice(-20);

const historyString = recentRows.map(r => `${r.role === 'user' ? 'USER' : 'ASSISTANT'}: ${r.content}`).join('\n');

return {
  json: {
    chatId,
    sheetId,
    firstName,
    source,
    text: currentText,
    query: currentText,
    sessionId,
    today,
    historyMessages: recentRows,
    historyJson: JSON.stringify(recentRows),
    chatHistory: historyString || 'No history'
  }
};

const crypto = require('crypto');
return { 
  json: { 
    chatId: $json.chatId, 
    firstName: $json.firstName, 
    state: crypto.randomBytes(32).toString('hex'), 
    createdAt: new Date().toISOString() 
  } 
};

const CLIENT_ID = (typeof $env !== 'undefined' && $env.GOOGLE_OAUTH_CLIENT_ID) || 'your_google_oauth_client_id_here';
    const REDIRECT_URI = (typeof $env !== 'undefined' && $env.GOOGLE_OAUTH_REDIRECT_URI) || 'https://debtless-creation-goal.ngrok-free.dev/webhook/google-oauth-callback';
    const input = $input.first().json;

    const paramsStr = "client_id=" + encodeURIComponent(CLIENT_ID) +
      "&redirect_uri=" + encodeURIComponent(REDIRECT_URI) +
      "&response_type=code" +
      "&scope=" + encodeURIComponent("openid email profile https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/drive.file") + "&access_type=offline" + "&prompt=consent" + "&state=" + encodeURIComponent(input.state);

    return { 
      json: {
        ...input,
        authUrl: 'https://accounts.google.com/o/oauth2/v2/auth?' + paramsStr
      }
    };

let raw = '';
try {
  raw = ($input.item.json?.choices?.[0]?.message?.content || '').trim();
} catch (e) {}

let route = 'mill';
let confidence = 0.9;

if (raw) {
  try {
    const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    route = (parsed.route || 'mill').toLowerCase();
    confidence = parseFloat(parsed.confidence) || 0.9;
    if (route !== 'mill' && route !== 'chatur') route = 'mill';
  } catch(e) {
    route = raw.toLowerCase().includes('chatur') ? 'chatur' : 'mill';
  }
}

return {
  json: {
    ...$('Build Messages Array').item.json,
    route,
    confidence
  }
};

const update = $input.item.json;
const message = update.message;

if (!message || !message.chat || !message.chat.id) {
  return [];
}

const chatId = message.chat.id;
const messageId = message.message_id || null;
const userId = message.from ? message.from.id : null;
const firstName = message.from ? (message.from.first_name || 'User') : 'User';
const text = message.text || '';
const updateId = update.update_id || null;

// Unique event identifier
const eventId = `telegram:${chatId}:${messageId || updateId || text}`;

// Deduplication Gate (in-memory Map with 5 minute TTL)
if (!globalThis._sevai_seen_events) {
  globalThis._sevai_seen_events = new Map();
}

const now = Date.now();
// Clean entries older than 5 minutes
for (const [k, v] of globalThis._sevai_seen_events.entries()) {
  if (now - v > 300000) {
    globalThis._sevai_seen_events.delete(k);
  }
}

// If event was seen within the last 5 minutes, abort immediately (blocks Telegram retry duplicates)
if (globalThis._sevai_seen_events.has(eventId)) {
  return [];
}

// Mark event as seen
globalThis._sevai_seen_events.set(eventId, now);

return {
  json: {
    eventId,
    updateId,
    messageId,
    chatId,
    userId,
    firstName,
    text,
    timestamp: new Date().toISOString()
  }
};

// ─── RESPONSE GUARD ──────────────────────────────────────────────────────────
// Sits between Execute Mill/Chatur and memory + Telegram.
// Normalizes any response format and guards against empty/JSON/malformed output.
// Sanitizes Telegram Markdown entities to prevent 400 Bad Request parser errors.

const input = $input.item.json;

// 1. Pick up agentId and raw response from the standard contract
const agentId = input.agent || input.agentId || 'mill';
let response   = input.response ?? input.output ?? input.agentResponse ?? input.text ?? '';

// 2. Convert to string
response = String(response).trim();

// 3. Strip markdown code fences
response = response
  .replace(/^```(?:json|text|markdown|plain)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// 4. If model accidentally wrapped in JSON, unwrap it
try {
  const parsed = JSON.parse(response);
  if (parsed !== null && typeof parsed === 'object') {
    response =
      parsed.response ??
      parsed.message ??
      parsed.text ??
      parsed.output ??
      response;
    response = String(response).trim();
  }
} catch (e) {}

// 5. Strip the 'Chatur says:' / 'Mill says:' prefixes if still present
response = response.replace(/^(chatur|mill)\s+says:\s*/i, '').trim();

// 6. TELEGRAM MARKDOWN SANITIZER (Fixes byte offset 400 parse errors)
// A. Convert asterisk/hyphen bullet markers to unicode bullet dots so they never conflict with bold entities
response = response.replace(/^(\s*)[*+-]\s+/gm, '$1• ');

// B. Convert double-asterisk **bold** to single *bold*
response = response.replace(/\*\*([^\*\n]+)\*\*/g, '*$1*');

// C. Balance asterisks
let asteriskCount = (response.match(/\*/g) || []).length;
if (asteriskCount % 2 !== 0) {
  const lastIdx = response.lastIndexOf('*');
  if (lastIdx !== -1) {
    response = response.substring(0, lastIdx) + response.substring(lastIdx + 1);
  }
}

// D. Balance underscores
let underscoreCount = (response.match(/_/g) || []).length;
if (underscoreCount % 2 !== 0) {
  const lastUnderscore = response.lastIndexOf('_');
  if (lastUnderscore !== -1) {
    response = response.substring(0, lastUnderscore) + response.substring(lastUnderscore + 1);
  }
}

// 7. Final empty guard
if (!response || response.length < 2) {
  response = "Sorry, I couldn't generate a response. Please try again! 🙏";
}

// 8. Pull in context for memory writes
const ctx = $('Build Messages Array').item.json;

return {
  json: {
    chatId:        ctx.chatId,
    sheetId:       ctx.sheetId,
    firstName:     ctx.firstName,
    source:        ctx.source,
    sessionId:     ctx.sessionId,
    today:         ctx.today,
    agentId:       agentId,
    agentResponse: response
  }
};

const users = $input.all();
    const currentChatId = $('Extract Telegram Metadata').item.json.chatId;

    const validUsers = users.filter(u => u.json && u.json.chatId && u.json.chatId != '');
    const foundUser = validUsers.find(u => u.json.chatId == currentChatId);

    if (foundUser && foundUser.json && foundUser.json.sheetId) {
      return {
        json: {
          ...$('Extract Telegram Metadata').item.json,
          isRegisteredUser: true,
          sheetId: foundUser.json.sheetId,
          appToken: foundUser.json.appToken
        }
      };
    } else {
      return {
        json: {
          ...$('Extract Telegram Metadata').item.json,
          isRegisteredUser: false
        }
      };
    }

const item = $('Event Normalizer').first().json;
const devResult = $input.first().json || {};
const analytics = item.analytics || {};

const insertedCount = devResult.insertedCount !== undefined ? devResult.insertedCount : (analytics.totalCount || 0);
const skippedCount = devResult.skippedCount || 0;
const totalSpent = (analytics.totalSpent || 0).toLocaleString('en-IN');
const totalIncome = (analytics.totalIncome || 0).toLocaleString('en-IN');

let catLines = '';
if (analytics.topCategories && analytics.topCategories.length > 0) {
  catLines = analytics.topCategories.slice(0, 4).map(c => {
    return `• ${c.category}: ₹${c.total.toLocaleString('en-IN')} (${c.count} txs)`;
  }).join('\n');
} else {
  catLines = '• General Expenses logged';
}

const maxLine = analytics.maxExpense > 0 ? `📈 *Largest Expense:* ₹${analytics.maxExpense.toLocaleString('en-IN')} (${analytics.maxVendor})` : '';
const minLine = analytics.minExpense > 0 ? `📉 *Smallest Spend:* ₹${analytics.minExpense.toLocaleString('en-IN')} (${analytics.minVendor})` : '';

const message = `📲 *1-Month Spending Pretext Synced!*
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
✅ *${insertedCount} Transactions Logged*
${skippedCount > 0 ? `⚠️ *${skippedCount} Duplicates Skipped*\n` : ''}💰 *Total Spent:* ₹${totalSpent}${analytics.totalIncome > 0 ? ` | *Earned:* ₹${totalIncome}` : ''}

📊 *Key Spending Categories:*
${catLines}
${maxLine ? `\n${maxLine}` : ''}${minLine ? `\n${minLine}` : ''}

✨ _Your historical pretext is loaded! Your charts, trend analytics, and coach insights are now active._
🔗 [Open Live Dashboard](http://localhost:3000/?sheetId=${item.sheetId})`;

return {
  json: {
    chatId: item.chatId,
    sheetId: item.sheetId,
    summaryText: message,
    success: true,
    insertedCount,
    skippedCount
  }
};
